SELECT t1.* FROM stock_indicator t1
INNER JOIN (
    SELECT stock_code, MAX(trade_time) as max_time
    FROM stock_indicator
    WHERE stock_code IN

        #{code}

    AND kline_type = #{klineType}
    GROUP BY stock_code
) t2 ON t1.stock_code = t2.stock_code AND t1.trade_time = t2.max_time
AND t1.kline_type = #{klineType}


where kline_type = #{klineType}

    and stock_code in

        #{code}



    and trade_time >= #{startDate}


    and trade_time <= #{endDate}

order by stock_code asc, trade_time asc
